105	    /**
106	     * The membership level is capped at this value; level 4 is reserved for tenure.
107	     */
108	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
109	
110	    /**
111	     * Returns the owner's membership level, a number from 1 to
112	     * {@value #MAX_MEMBERSHIP_LEVEL} assigned at creation: it starts at 1, gains 1 when
113	     * an email address is present, gains 1 when the owner has no namesakes
114	     * (namesakeCount is 0), and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is
115	     * reserved for tenure).
116	     */
117	    public static int membershipLevel(Owner owner) {
118	        int level = 1;
119	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
120	        if (hasEmail) {
121	            level++;
122	        }
123	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
124	        if (noNamesakes) {
125	            level++;
126	        }
