142	    /**
143	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
144	     * been created for this owner's {@code registrationDate}, using the same per-day
145	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
146	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
147	     */
148	    protected boolean bulkSignupWarning(Owner owner) {
149	        LocalDate registrationDate = owner.getRegistrationDate();
150	        if (registrationDate == null) {
151	            return false;
152	        }
153	        long count = ownerRepository.findAll().stream()
154	                .filter(existing -> !existing.getId().equals(owner.getId()))
155	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
156	                .count();
157	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
158	    }
