160	    /**
161	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
162	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
163	     * legacy seed owners).
164	     */
165	    protected Integer checkDigit(Owner owner) {
166	        String customerCode = owner.getCustomerCode();
167	        if (customerCode == null) {
168	            return null;
169	        }
170	        int sum = 0;
171	        boolean dbl = true;
172	        for (int i = customerCode.length() - 1; i >= 0; i--) {
173	            char c = customerCode.charAt(i);
174	            if (c < '0' || c > '9') {
175	                continue;
176	            }
177	            int d = c - '0';
178	            if (dbl) {
179	                d *= 2;
180	                if (d > 9) {
181	                    d -= 9;
182	                }
183	            }
184	            sum += d;
185	            dbl = !dbl;
186	        }
187	        return (10 - (sum % 10)) % 10;
188	    }
189	
190	    public abstract Owner toOwner(OwnerDto ownerDto);
191	
